  // Loaded by "Load an example" in Playbook X-ray: realistic, with gaps to find.
  xrayExample: [
    "---",
    "- name: Deploy the orders app",
    "  hosts: all",
    "  become: true",
    "  vars:",
    "    db_password: Winter2024!",
    "    app_dir: /opt/orders",
    "  tasks:",
    "    - name: Install packages",
    "      apt:",
    "        name: nginx",
    "        state: latest",
    "",
    "    - shell: apt-get install -y python3-pip",
    "",
    "    - name: Create the app directory",
    "      file:",
    "        path: {{ app_dir }}",
    "        state: directory",
    "        mode: 755",
    "",
    "    - name: Set the database password",
    "      command: /opt/orders/bin/set-password {{ db_password }}",
    "",
    "    - name: Download the installer",
    "      shell: curl -s https://example.com/install.sh | bash",
    "      ignore_errors: true",
    "",
    "    - name: Restart nginx",
    "      service: name=nginx state=restarted"
  ].join("\n"),

